<script setup>
import DataGrid from './DataGrid.vue';
defineProps({diff:{type:Object,required:true},format:{type:Function,required:true}});
</script>
<template><section class="snapshot-comparison" aria-label="Snapshot comparison"><h4>Current Configuration Compared With Snapshot</h4><p v-if="diff.matches" role="status">All items listed in this review match this snapshot. No differences detected.</p><template v-else><p>{{diff.changes.length}} differences detected. This review does not overwrite anything. Items present only in current configuration require separate review and are not automatically deleted.</p><DataGrid><thead><tr><th>Item</th><th>Difference</th></tr></thead><tbody><tr v-for="item in diff.changes" :key="item.name"><td>{{item.name}}</td><td>{{item.status}}</td></tr></tbody></DataGrid></template><details v-for="(item,index) in diff.matches?diff.items:diff.changes" :key="item.name" :open="!diff.matches&&index===0"><summary>{{item.name}} · {{item.status}}</summary><div class="coverage-diff"><article><h5>Current Configuration</h5><pre>{{format(item.current)}}</pre></article><article><h5>Saved Snapshot</h5><pre>{{format(item.saved)}}</pre></article></div></details></section></template>
